<script setup lang="ts">
import { ref } from 'vue'; import Button from 'primevue/button'; import Dialog from 'primevue/dialog'; import InputNumber from 'primevue/inputnumber'; import InputText from 'primevue/inputtext'; import Select from 'primevue/select'; import Textarea from 'primevue/textarea'; import { useToast } from 'primevue/usetoast'; import { api } from '../lib/api'; import { useQuery } from '../composables/useQuery'; import { money, date, serviceNames, type Data } from '../lib/types'; import QueryState from '../components/QueryState.vue'; import StatusBadge from '../components/StatusBadge.vue';
const {data,loading,error,refresh}=useQuery(()=>api('/admin/fare-policies'));const zones=useQuery(()=>api('/admin/service-zones'));const show=ref(false),publish=ref<Data>(),publishVisible=ref(false),reason=ref(''),busy=ref(false),toast=useToast();const form=ref({serviceTypeCode:'BIKE',name:'GrapBike',baseFare:12000,perKm:4500,perMinute:300,minimumFare:15000,serviceFee:2000,commissionRate:.2});
async function save(){busy.value=true;try{await api('/admin/fare-policies',{method:'POST',body:form.value});show.value=false;await refresh();toast.add({severity:'success',summary:'Đã tạo phiên bản giá nháp',life:3000});}catch(e){toast.add({severity:'error',summary:(e as Error).message,life:5000});}finally{busy.value=false;}}
async function commit(){if(!publish.value)return;busy.value=true;try{await api('/admin/fare-policies/'+publish.value.id+'/publish',{method:'POST',body:{expectedVersion:publish.value.version,effectiveAt:new Date().toISOString(),reasonCode:reason.value}});publishVisible.value=false;await refresh();toast.add({severity:'success',summary:'Đã phát hành bảng giá mới',life:3000});}catch(e){toast.add({severity:'error',summary:(e as Error).message,life:5000});}finally{busy.value=false;}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">CHÍNH SÁCH VẬN HÀNH</div><h1>Giá cước & vùng dịch vụ<span class="green-text">.</span></h1><p>Phiên bản giá minh bạch. Mỗi hành trình giữ nguyên giá đã chốt.</p></div><Button label="Tạo bảng giá mới" icon="pi pi-plus" @click="show=true"/></div><div class="info-box page-info"><i class="pi pi-lock"></i><div><strong>Bảng giá đã phát hành được giữ nguyên</strong><p>Mọi thay đổi tạo phiên bản mới. Báo giá còn hạn và chuyến đang chạy tiếp tục dùng snapshot ban đầu.</p></div></div><QueryState :loading="loading" :error="error" @retry="refresh"/><div v-if="data" class="pricing-grid"><section v-for="p in data.items" :key="p.id" class="panel pricing-card"><div class="pricing-header"><span class="service-illustration" :class="p.serviceTypeCode==='BIKE'?'mint':'lavender'"><i class="pi" :class="p.serviceTypeCode==='BIKE'?'pi-directions':'pi-car'"></i></span><StatusBadge :status="p.status"/></div><h2>{{serviceNames[p.serviceTypeCode]}}</h2><p class="muted">{{p.name}} · Phiên bản {{p.version}}</p><div class="pricing-base"><strong>{{money(p.baseFare)}}</strong><span>giá mở cửa</span></div><div class="fare-breakdown"><div><span>Cước quãng đường</span><b>{{money(p.perKm)}} / km</b></div><div><span>Cước thời gian</span><b>{{money(p.perMinute)}} / phút</b></div><div><span>Giá tối thiểu</span><b>{{money(p.minimumFare)}}</b></div><div><span>Phí dịch vụ</span><b>{{money(p.serviceFee)}}</b></div><div><span>Hoa hồng vận chuyển</span><b>{{(p.commissionRate*100).toFixed(0)}}%</b></div></div><div class="pricing-footer"><span><i class="pi pi-calendar"></i> {{date(p.effectiveFrom,false)}}</span><Button v-if="p.status==='DRAFT'" label="Xem trước & phát hành" text size="small" @click="publish=p;publishVisible=true;reason=''"/><span v-else class="muted">Giá đã có phiên bản</span></div></section></div><section class="panel zone-panel"><div class="panel-header"><div><h2>Vùng phục vụ</h2><p>Phạm vi được kiểm tra tại backend trước khi tạo báo giá</p></div><i class="pi pi-map green-text"></i></div><div v-for="zone in zones.data.value?.items ?? []" :key="zone.id" class="zone-row"><span class="metric-icon green"><i class="pi pi-building"></i></span><div><strong>{{zone.name}}</strong><p>Asia/Ho_Chi_Minh · VND · Phiên bản {{zone.version}}</p></div><StatusBadge :status="zone.active?'ACTIVE':'SUSPENDED'"/></div></section><Dialog v-model:visible="show" modal header="Tạo phiên bản giá" :style="{width:'560px'}"><div class="form-grid"><label>Dịch vụ<Select v-model="form.serviceTypeCode" :options="Object.entries(serviceNames).map(([value,label])=>({value,label}))" option-label="label" option-value="value"/></label><label>Tên bảng giá<InputText v-model="form.name"/></label><label>Giá mở cửa (đ)<InputNumber v-model="form.baseFare" :min="0" :max-fraction-digits="0"/></label><label>Cước / km (đ)<InputNumber v-model="form.perKm" :min="0" :max-fraction-digits="0"/></label><label>Cước / phút (đ)<InputNumber v-model="form.perMinute" :min="0" :max-fraction-digits="0"/></label><label>Giá tối thiểu (đ)<InputNumber v-model="form.minimumFare" :min="0" :max-fraction-digits="0"/></label><label>Phí dịch vụ (đ)<InputNumber v-model="form.serviceFee" :min="0" :max-fraction-digits="0"/></label><label>Tỷ lệ hoa hồng (0–0,5)<InputNumber v-model="form.commissionRate" :min="0" :max=".5" :step=".01" :min-fraction-digits="2"/></label></div><template #footer><Button label="Quay lại" text severity="secondary" @click="show=false"/><Button label="Lưu bản nháp" :loading="busy" @click="save"/></template></Dialog><Dialog v-model:visible="publishVisible" modal header="Xem trước & phát hành" :style="{width:'480px'}"><template v-if="publish"><p>Phát hành <strong>{{publish.name}} · v{{publish.version}}</strong> có hiệu lực ngay.</p><div class="info-box"><i class="pi pi-calculator"></i><p>Ví dụ tuyến 6 km, 20 phút: <strong>{{money(Math.max(publish.minimumFare,publish.baseFare+publish.perKm*6+publish.perMinute*20)+publish.serviceFee)}}</strong>. Chưa gồm phụ phí được chấp thuận.</p></div><label>Lý do phát hành<Textarea v-model="reason" rows="3" class="full-width"/></label></template><template #footer><Button label="Quay lại" text severity="secondary" @click="publishVisible=false"/><Button label="Phát hành bảng giá" :disabled="reason.trim().length<3" :loading="busy" @click="commit"/></template></Dialog></template>
